#include <fstream>
#include <iostream>
#include <iomanip>
#include "tools/dump_format.hpp"
using namespace adas_mgm;
int main(int argc,char**argv){std::ifstream f(argv[1],std::ios::binary);DumpHeader h{};f.read((char*)&h,sizeof(h));if(h.magic!=kDumpMagic||h.version!=kDumpVersion||h.snapshot_size!=sizeof(CoreSnapshot)||h.params_size!=sizeof(CoreParams))return 2; CoreSnapshot s{};int tick=0;std::cout<<"tick,event_time_ns,gps_x,gps_y,gps_position_valid,gps_track_index,vehicle_speed,vehicle_speed_valid,lane_confidence,gps_cross_track,gps_station_yaw_error,gps_heading_valid,avoid_obstacle_detected,avoid_avoidable,avoid_narrow_gap,avoid_maneuver_done,avoid_v_suggest,avoid_ttc,parking_v_suggest,parking_done,parking_path_blocked,traffic_red_active,traffic_green_active,traffic_stopline_detected,traffic_stop_distance,autonomous_enabled,external_stop,camera_available,gps_fixed_ready,lidar_valid,gps_fix_quality,sensor_alive_mask,front_clearance_m,left_clearance_m,right_clearance_m,lane_age_s,lane_timeout_s,gps_age_s,gps_timeout_s,avoid_age_s,avoid_timeout_s,parking_age_s,parking_timeout_s,recovery_age_s,recovery_timeout_s,avoid_points\n"<<std::setprecision(14);while(f.read((char*)&s,sizeof(s))){std::cout<<tick++<<","<<+(s.event_time_ns)<<","<<+(s.gps_x)<<","<<+(s.gps_y)<<","<<+(s.gps_position_valid)<<","<<+(s.gps_track_index)<<","<<+(s.vehicle_speed)<<","<<+(s.vehicle_speed_valid)<<","<<+(s.lane_confidence)<<","<<+(s.gps_cross_track)<<","<<+(s.gps_station_yaw_error)<<","<<+(s.gps_heading_valid)<<","<<+(s.avoid_obstacle_detected)<<","<<+(s.avoid_avoidable)<<","<<+(s.avoid_narrow_gap)<<","<<+(s.avoid_maneuver_done)<<","<<+(s.avoid_v_suggest)<<","<<+(s.avoid_ttc)<<","<<+(s.parking_v_suggest)<<","<<+(s.parking_done)<<","<<+(s.parking_path_blocked)<<","<<+(s.traffic_red_active)<<","<<+(s.traffic_green_active)<<","<<+(s.traffic_stopline_detected)<<","<<+(s.traffic_stop_distance)<<","<<+(s.autonomous_enabled)<<","<<+(s.external_stop)<<","<<+(s.camera_available)<<","<<+(s.gps_fixed_ready)<<","<<+(s.lidar_valid)<<","<<+(s.gps_fix_quality)<<","<<+(s.sensor_alive_mask)<<","<<+(s.estop_clearance_m[0])<<","<<+(s.estop_clearance_m[1])<<","<<+(s.estop_clearance_m[2])<<","<<+(s.references[0].age_s)<<","<<+(s.references[0].timeout_s)<<","<<+(s.references[1].age_s)<<","<<+(s.references[1].timeout_s)<<","<<+(s.references[2].age_s)<<","<<+(s.references[2].timeout_s)<<","<<+(s.references[3].age_s)<<","<<+(s.references[3].timeout_s)<<","<<+(s.references[4].age_s)<<","<<+(s.references[4].timeout_s)<<","<<+(s.avoid_path.n)<<"\n";}return 0;}
